package pillar.projectionworker.config

data class ProjectionWorkerConfig(val databaseUrl:String, val ledgerHost:String, val ledgerPort:Int, val pqsUrl:String, val participantId:String, val environment:String, val synchronizerId:String, val projectorNamePrefix:String, val lagSloSeconds:Long, val backpressureThresholdSeconds:Long){ companion object { fun fromEnv(env: Map<String,String> = System.getenv()) = ProjectionWorkerConfig(env["DATABASE_URL"] ?: "jdbc:postgresql://localhost/postgres", env["LEDGER_HOST"] ?: "localhost", (env["LEDGER_PORT"] ?: "6865").toInt(), env["PQS_URL"] ?: env["DATABASE_URL"] ?: "jdbc:postgresql://localhost/postgres", env["PARTICIPANT_ID"] ?: "participant", env["ENVIRONMENT"] ?: "test", env["SYNCHRONIZER_ID"] ?: "sync", env["PROJECTOR_NAME_PREFIX"] ?: "pillar", (env["LAG_SLO_SECONDS"] ?: "30").toLong(), (env["BACKPRESSURE_THRESHOLD_SECONDS"] ?: "10").toLong()) } }
